import{_ as t}from"./chunks/emo.Cly4kUfc.js";import{_ as i}from"./chunks/emergency-button-gui.Dns_dYnB.js";import{_ as s,o,c as e,a5 as n}from"./chunks/framework.DGp912Ge.js";const _=JSON.parse('{"title":"6-3. 비상 정지 및 복구","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/common/emo.md","filePath":"ko/guides/common/emo.md","lastUpdated":1785806767000}'),r={name:"ko/guides/common/emo.md"};function l(c,a,d,p,g,m){return o(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="_6-3-비상-정지-및-복구" tabindex="-1">6-3. 비상 정지 및 복구 <a class="header-anchor" href="#_6-3-비상-정지-및-복구" aria-label="Permalink to &quot;6-3. 비상 정지 및 복구&quot;">​</a></h1><p><strong>목표:</strong> 비상 상황에서 즉시 로봇을 정지하는 방법과 안전하게 작동을 재개하는 방법을 숙지합니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>로봇 작동 중에는 비상 정지 버튼에 항상 접근할 수 있는 상태를 유지하세요. 로봇이 사람이나 재산에 위험을 초래할 수 있는 상황에서는 즉시 비상 정지 버튼을 누르세요.</p></div></div><h2 id="물리적-비상-정지-버튼" tabindex="-1">물리적 비상 정지 버튼 <a class="header-anchor" href="#물리적-비상-정지-버튼" aria-label="Permalink to &quot;물리적 비상 정지 버튼&quot;">​</a></h2><figure><img src="'+t+'" alt="로봇 후면의 비상 정지 버튼"><figcaption style="text-align:center;">[ 비상 정지 누름 버튼 — 로봇 후면에 위치 ]</figcaption></figure><p><strong>비상 정지 버튼</strong>을 누르면:</p><ul><li>모든 관절이 <strong>High Damping</strong> 모드로 전환됩니다.</li><li>로봇은 외부 움직임에 저항하지만 토크나 위치 명령을 <strong>받지 않습니다</strong>.</li><li>자세를 유지하지 못하고 중력에 의해 바닥으로 내려앉을 수 있습니다.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>High Damping 모드는 사용자와 로봇 모두를 보호합니다. 비상 정지가 해제되고 로봇이 재초기화될 때까지 어떤 동작 명령도 실행되지 않습니다.</p></div></div><h2 id="gui-비상-정지" tabindex="-1">GUI 비상 정지 <a class="header-anchor" href="#gui-비상-정지" aria-label="Permalink to &quot;GUI 비상 정지&quot;">​</a></h2><p>물리적 버튼에 접근하지 않고도 RBQGUI에서 비상 정지를 실행할 수 있습니다.</p><figure><img src="'+i+'" alt="RBQGUI의 비상 정지 버튼"><figcaption style="text-align:center;">[ RBQGUI 상단 표시줄의 EMERGENCY 버튼 ]</figcaption></figure><p>RBQGUI 상단 표시줄의 <strong>EMERGENCY</strong> 버튼을 누르면 물리적 버튼과 동일하게 모든 관절이 즉시 High Damping 모드로 전환됩니다.</p><h2 id="복구-절차" tabindex="-1">복구 절차 <a class="header-anchor" href="#복구-절차" aria-label="Permalink to &quot;복구 절차&quot;">​</a></h2><p>비상 정지 후 다음 단계에 따라 안전하게 작동을 재개합니다:</p><ol><li><strong>안전 확인</strong> — 로봇 주변 2m 이내에 사람이나 동물이 없는지 확인합니다.</li><li><strong>버튼 해제</strong> — 물리적 비상 정지 버튼을 시계 방향으로 돌려 잠금 해제합니다.</li><li><strong>초기 자세로 복귀</strong> — 로봇이 넘어지거나 위치가 바뀐 경우, 평평한 바닥에서 <a href="/RBQ/ko/guides/common/initial-pose.html">올바른 초기 자세</a>로 수동으로 되돌립니다.</li><li><strong>재초기화</strong> — RBQGUI에서 <strong>Stance</strong> 버튼을 누르거나, <a href="/RBQ/ko/guides/common/controller-wifi-connect.html#auto-start">컨트롤러 &amp; Wi-Fi</a> 설정에서 <strong>Auto Start</strong>를 실행합니다.</li><li><strong>확인</strong> — 작동 재개 전 EMERGENCY 표시등이 꺼지고 Auto Start 항목이 모두 초록색인지 확인합니다.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>High Damping 모드 상태에서 관절을 강제로 움직이지 마세요. 비상 정지를 해제한 후 천천히 초기 자세로 복귀시키세요.</p></div></div><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/ko/manual/safety/general-safety-warning-precautions.html">일반 안전 지침</a></li><li><a href="/RBQ/ko/manual/safety/emergency-stop-procedures.html">비상 정지 절차 (상세)</a></li><li><a href="/RBQ/ko/guides/common/initial-pose.html">초기 자세 설정 및 전원 켜기</a></li></ul>',18)])])}const b=s(r,[["render",l]]);export{_ as __pageData,b as default};
